var DATA = {"system": "Pumped storage", "objective": "Maximize spread capture", "units": "name=pump,cost=30,cap=200|name=gen,cost=-100,cap=200", "demand": "150"};
console.log("System: " + DATA.system + " | Objective: " + DATA.objective);
var demand = parseFloat(DATA.demand);
// units like "coal:cost=30,cap=500|gas:cost=50,cap=300|solar:cost=5,cap=200"
var units = DATA.units.split("|").map(function (u) {
  var p = {};
  u.split(",").forEach(function (kv) {
    var q = kv.split("=").map(function (s) { return s.trim(); });
    p[q[0]] = isNaN(parseFloat(q[1])) ? q[1] : parseFloat(q[1]);
  });
  return p;
});
units.sort(function (a, b) { return a.cost - b.cost; }); // merit order
console.log("Merit order (cheapest first):");
var remaining = demand, totalCost = 0, served = 0;
units.forEach(function (u) {
  var use = Math.min(u.cap, remaining);
  remaining -= use; served += use; totalCost += use * u.cost;
  console.log("  " + (u.name || "unit") + ": cost=" + u.cost + " cap=" + u.cap + " -> dispatch " + use);
});
console.log("Demand: " + demand + " | Served: " + served + " | Unserved: " + remaining + " | Cost: " + totalCost);
